mapper.select:
SELECT * FROM donation
ORDER BY created_at DESC
    LIMIT #{limit}

mapper.update:
UPDATE donation
SET status = #{status}, updated_at = NOW()
WHERE donation_id = #{donationId}

UPDATE donation
SET view_count = view_count + 1, updated_at = NOW()
WHERE donation_id = #{donationId}

UPDATE donation
SET is_emergency = #{isEmergency}, updated_at = NOW()
WHERE donation_id = #{donationId}
